import { Component, Input, Output, EventEmitter } from '@angular/core';
import { FormBuilder, Validators } from '@angular/forms';
import { ResenasService } from '../../core/services/resenas.service';

@Component({
  selector: 'app-rating-form',
  templateUrl: './rating-form.component.html',
  styleUrls: ['./rating-form.component.scss']
})
export class RatingFormComponent {
  @Input() compaId!: number;
  @Output() resenaCreada = new EventEmitter<void>();

  form = this.fb.group({
    puntuacion: [0, [Validators.required, Validators.min(1), Validators.max(5)]],
    comentario: ['', Validators.maxLength(500)]
  });

  submitting = false;
  error      = '';
  success    = '';

  constructor(private fb: FormBuilder, private resenasService: ResenasService) {}

  setStars(n: number): void {
    this.form.patchValue({ puntuacion: n });
  }

  submit(): void {
    if (this.form.invalid || this.submitting) return;

    this.submitting = true;
    this.error      = '';
    const puntuacion = this.form.get('puntuacion')!.value as number;
    const comentario = this.form.get('comentario')!.value as string;

    this.resenasService.create(this.compaId, {
      puntuacion,
      comentario: comentario || ''
    }).subscribe({
      next: () => {
        this.success = '¡Reseña publicada exitosamente!';
        this.submitting = false;
        setTimeout(() => this.resenaCreada.emit(), 1200);
      },
      error: (err) => {
        this.error      = err.error?.error ?? 'Error al publicar la reseña.';
        this.submitting = false;
      }
    });
  }
}
<div class="rating-form card">
  <h3>Deja tu calificación</h3>

  <div class="alert alert-error"   *ngIf="error">{{ error }}</div>
  <div class="alert alert-success" *ngIf="success">{{ success }}</div>

  <form [formGroup]="form" (ngSubmit)="submit()" *ngIf="!success">

    <div class="form-group">
      <label>Puntuación <span class="required">*</span></label>
      <div class="stars-picker">
        <app-star-rating
          [value]="form.value.puntuacion ?? 0"
          (valueChange)="setStars($event)"
          size="lg"
        ></app-star-rating>
        <span class="stars-hint" *ngIf="(form.value.puntuacion ?? 0) === 0">Haz clic en una estrella</span>
      </div>
      <span class="error-msg" *ngIf="form.controls['puntuacion'].invalid && form.controls['puntuacion'].touched">
        Selecciona una puntuación.
      </span>
    </div>

    <div class="form-group">
      <label>Comentario (opcional)</label>
      <textarea
        formControlName="comentario"
        placeholder="Describe tu experiencia con este compa..."
        rows="4"
      ></textarea>
      <span class="char-count">{{ (form.value.comentario?.length ?? 0) }} / 500</span>
    </div>

    <button
      type="submit"
      class="btn btn-primary"
      [disabled]="form.invalid || submitting"
    >
      {{ submitting ? 'Publicando...' : 'Publicar reseña' }}
    </button>
  </form>
</div>
